    {
      "service": "ts-order-other-service",
      "fault_kind": "application_exception",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name = 'ts-order-other-service' AND level = 'SEVERE' GROUP BY ALL",
          "claim": "ts-order-other-service logs 497 SEVERE 'Unexpected error' RuntimeException entries in the incident window."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-order-other-service' AND attr_status_code = 'Error' GROUP BY ALL",
          "claim": "Refresh handler spans in ts-order-other-service fail with Error status (about 497 each); none in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE span_name = 'POST /api/v1/orderOtherService/orderOther/refresh' GROUP BY ALL",
          "claim": "The user-facing refresh call from ts-ui-dashboard fails for every request that reaches ts-order-other-service."
        }
      ]
    },
    {
      "service": "ts-order-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_k8s_pod_name AS pod, round(duration/1e6,1) AS ms FROM abnormal_traces WHERE service_name = 'ts-order-service' AND span_name = 'SELECT ts.orders' AND duration > 1000000000 ORDER BY duration DESC",
          "claim": "ts-order-service's SELECT ts.orders DB calls stall for about 3.5 s; normal max is about 99 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) FILTER (WHERE duration > 1000000000) AS over_1s, count(*) AS n FROM abnormal_traces WHERE span_name IN ('GET /api/v1/orderservice/order/security/{checkDate}/{accountId}', 'SecurityController.check', 'POST /api/v1/preserveservice/preserve') GROUP BY ALL",
          "claim": "Order security-check calls exceeding 1 s also show up in security-check and preserve spans."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(duration/1e6,1) AS ms FROM abnormal_traces WHERE service_name = 'ts-security-service' AND span_name IN ('GET', 'SecurityController.check') AND duration > 1000000000 ORDER BY duration DESC",
          "claim": "Security's outgoing GET to order-service takes about 2.4 s when order's DB call stalls."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-preserve-service' AND span_name = 'PreserveController.preserve' GROUP BY ALL",
          "claim": "Preserve p95 rises from about 193 ms in normal to about 379 ms in the incident window, driven by security-call stalls."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND span_name = 'POST /api/v1/preserveservice/preserve' GROUP BY ALL",
          "claim": "The user-facing preserve request at ts-ui-dashboard has p95 near 1.5 s in the incident, versus about 450 ms normal."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND span_name = 'POST /api/v1/orderOtherService/orderOther/refresh' GROUP BY ALL",
          "claim": "Every ts-ui-dashboard refresh call to order-other ends in Error status, surfacing a user-visible failure."
        }
      ]
    }
  ]
}
